import{_ as e,C as a,c as t,o as i,j as o,G as s,b as r,a0 as n,a as d,w as l,a1 as c}from"./chunks/framework.DKRgXLPU.js";const u=JSON.parse('{"title":"Creando tu plan de entrenamiento","description":"","frontmatter":{},"headers":[],"relativePath":"es/education/goals/planning.md","filePath":"es/education/goals/planning.md"}');const p=e({name:"es/education/goals/planning.md"},[["render",function(e,u,p,m,b,h){const g=a("AdBanner"),f=a("Mermaid"),v=a("AdInArticle");return i(),t("div",null,[u[1]||(u[1]=o("h1",{id:"creando-tu-plan-de-entrenamiento",tabindex:"-1"},[d("Creando tu plan de entrenamiento "),o("a",{class:"header-anchor",href:"#creando-tu-plan-de-entrenamiento","aria-label":'Permalink to "Creando tu plan de entrenamiento"'},"​")],-1)),s(g),u[2]||(u[2]=o("p",null,"Las metas sin un plan son solo deseos. Esta guía te ayuda a convertir tus metas en un plan de entrenamiento estructurado que realmente funciona.",-1)),u[3]||(u[3]=o("div",{class:"tip custom-block"},[o("p",{class:"custom-block-title"},"La gran idea"),o("p",null,[o("strong",null,"Los objetivos sin un plan son sólo deseos."),d(" Un plan de entrenamiento estructurado transforma tus objetivos en acciones diarias que se traducen en un progreso real.")])],-1)),(i(),r(c,null,{default:l(()=>[s(f,{id:"mermaid-13",class:"mermaid",graph:"graph%20TD%0A%20%20%20%20A%5BMeta%5D%20--%3E%20B%5BPlan%20de%20entrenamiento%5D%0A%20%20%20%20B%20--%3E%20C%5BAcciones%20diarias%5D%0A%20%20%20%20C%20--%3E%20D%5BPr%C3%A1ctica%20consistente%5D%0A%20%20%20%20D%20--%3E%20E%5BProgreso%20medible%5D%0A%20%20%20%20E%20--%3E%20F%5BLogro%20de%20metas%5D%0A%0A%20%20%20%20style%20A%20fill%3A%23e3f2fd%0A%20%20%20%20style%20B%20fill%3A%23e8f5e9%0A%20%20%20%20style%20C%20fill%3A%23fff4e1%0A%20%20%20%20style%20F%20fill%3A%23fff4e1%0A"})]),fallback:l(()=>[...u[0]||(u[0]=[d(" Loading... ",-1)])]),_:1})),u[4]||(u[4]=n('<h2 id="las-8-fases-del-desarrollo-autodirigido" tabindex="-1">Las 8 fases del desarrollo autodirigido <a class="header-anchor" href="#las-8-fases-del-desarrollo-autodirigido" aria-label="Permalink to &quot;Las 8 fases del desarrollo autodirigido&quot;">​</a></h2><h3 id="fase-1-establece-tu-brujula-objetivos" tabindex="-1">Fase 1: Establece tu brújula (objetivos) <a class="header-anchor" href="#fase-1-establece-tu-brujula-objetivos" aria-label="Permalink to &quot;Fase 1: Establece tu brújula (objetivos)&quot;">​</a></h3><p>Ya aprendiste sobre los objetivos SMART. Ahora, ordénalos:</p><ol><li><strong>Objetivo a largo plazo</strong> (1-2 años): Tu sueño</li><li><strong>Objetivo anual</strong>: El objetivo de este año</li><li><strong>Objetivos trimestrales</strong>: hitos de 3 meses</li><li><strong>Objetivos mensuales</strong>: Áreas de enfoque específicas</li><li><strong>Objetivos semanales</strong>: Objetivos de entrenamiento</li></ol><h3 id="fase-2-evalue-sus-recursos" tabindex="-1">Fase 2: Evalúe sus recursos <a class="header-anchor" href="#fase-2-evalue-sus-recursos" aria-label="Permalink to &quot;Fase 2: Evalúe sus recursos&quot;">​</a></h3><p>Antes de planificar, evalúa honestamente lo que tienes:</p><table tabindex="0"><thead><tr><th>Recurso</th><th>Preguntas para hacer</th></tr></thead><tbody><tr><td><strong>Tiempo</strong></td><td>¿Cuántas horas por semana puedes entrenar de manera realista?</td></tr><tr><td><strong>Ubicación</strong></td><td>¿Tienes acceso a una pista adecuada? ¿Cuál es la calidad de la superficie?</td></tr><tr><td><strong>Equipo</strong></td><td>¿Tienes las bolas adecuadas? ¿Herramientas de medición? ¿Capacidad para grabar vídeos?</td></tr><tr><td><strong>Conocimiento</strong></td><td>¿Cuáles son sus fortalezas y debilidades técnicas?</td></tr><tr><td><strong>Condición física</strong></td><td>¿Alguna limitación? ¿Áreas que requieren trabajo?</td></tr></tbody></table><p>Sé honesto. Un plan realista supera una fantasía ambiciosa.</p><h3 id="fase-3-elige-tus-ejercicios" tabindex="-1">Fase 3: Elige tus ejercicios <a class="header-anchor" href="#fase-3-elige-tus-ejercicios" aria-label="Permalink to &quot;Fase 3: Elige tus ejercicios&quot;">​</a></h3><p>Seleccione ejercicios que apoyen directamente sus objetivos:</p><p><strong>Para mejorar la puntería:</strong></p><ul><li>Apuntado de precisión a zonas marcadas</li><li>Ejercicios de variación de distancia</li><li>Práctica de superficies diferentes</li></ul><p><strong>Para mejorar la toma de fotografías:</strong></p><ul><li>Escalera de tiro (distancias progresivas)</li><li>Tiro con obstáculos (arco alto forzado)</li><li>Práctica de tiro al blanco en movimiento</li></ul><p><strong>Para el desarrollo mental:</strong></p><ul><li>Práctica de rutina previa al disparo</li><li>Sesiones de visualización</li><li>Simulación de presión</li></ul><p><strong>Equilibra tu programa:</strong></p><ul><li>Trabajo técnico (apuntar, disparar)</li><li>Entrenamiento mental (mindfulness, visualización)</li><li>Acondicionamiento físico (equilibrio, flexibilidad)</li><li>Juego de partidos (aplicación de habilidades)</li></ul><h3 id="fase-4-crea-tu-horario" tabindex="-1">Fase 4: Crea tu horario <a class="header-anchor" href="#fase-4-crea-tu-horario" aria-label="Permalink to &quot;Fase 4: Crea tu horario&quot;">​</a></h3><p>Construye un horario semanal realista:</p>',20)),s(v),u[5]||(u[5]=n('<table tabindex="0"><thead><tr><th>Día</th><th>Mañana</th><th>Tarde</th><th>Noche</th><th>Enfocar</th></tr></thead><tbody><tr><td>Lun</td><td>-</td><td>Técnico: Apuntando</td><td>Movilidad ligera</td><td>Precisión</td></tr><tr><td>Mar</td><td>-</td><td>Técnico: Tiro</td><td>-</td><td>Potencia/precisión</td></tr><tr><td>Casarse</td><td>-</td><td>Entrenamiento mental</td><td>-</td><td>Consciencia</td></tr><tr><td>Jue</td><td>-</td><td>Mixto: Escenarios de juego</td><td>Movilidad ligera</td><td>Solicitud</td></tr><tr><td>Vie</td><td>-</td><td>Técnico: Debilidad</td><td>-</td><td>Mejora</td></tr><tr><td>Se sentó</td><td>Juego por partidos o competición</td><td>-</td><td>-</td><td>Actuación</td></tr><tr><td>Sol</td><td>Descansar</td><td>Revisión semanal</td><td>Planificación</td><td>Recuperación</td></tr></tbody></table><p><strong>Principios clave:</strong></p><ul><li>Priorizar el entrenamiento mental (a menudo se descuida)</li><li>Incluir días de descanso</li><li>Equilibrar diferentes habilidades</li><li>Deje la flexibilidad para toda la vida</li></ul><h3 id="fase-5-preparese-para-los-obstaculos" tabindex="-1">Fase 5: Prepárese para los obstáculos <a class="header-anchor" href="#fase-5-preparese-para-los-obstaculos" aria-label="Permalink to &quot;Fase 5: Prepárese para los obstáculos&quot;">​</a></h3><p>Las cosas saldrán mal. Planifica para ello.</p><table tabindex="0"><thead><tr><th>Riesgo</th><th>Probabilidad</th><th>Impacto</th><th>Plan de respaldo</th></tr></thead><tbody><tr><td>escasez de tiempo</td><td>Alto</td><td>Medio</td><td>Tenga preparada una &quot;sesión mínima&quot; (20 min)</td></tr><tr><td>Mal tiempo</td><td>Medio</td><td>Medio</td><td>Visualización en interiores, estudio de vídeo</td></tr><tr><td>Baja motivación</td><td>Alto</td><td>Medio</td><td>Regresa al &quot;por qué&quot;, objetivos más pequeños, tómate un descanso</td></tr><tr><td>Lesión menor</td><td>Medio</td><td>Alto</td><td>Centrarse en el entrenamiento mental, habilidades no afectadas</td></tr><tr><td>Sin compañero de práctica</td><td>Medio</td><td>Bajo</td><td>Ejercicios en solitario, autoanálisis en vídeo</td></tr></tbody></table><h3 id="fase-6-seguimiento-de-su-progreso" tabindex="-1">Fase 6: Seguimiento de su progreso <a class="header-anchor" href="#fase-6-seguimiento-de-su-progreso" aria-label="Permalink to &quot;Fase 6: Seguimiento de su progreso&quot;">​</a></h3><p>Lo que se mide se gestiona.</p><p><strong>Mantenga un diario de entrenamiento:</strong></p><ul><li>Fecha y duración</li><li>Ejercicios completados</li><li>Puntuaciones/resultados</li><li>Cómo te sentiste (energía, concentración, fluidez)</li><li>Notas técnicas</li><li>Clima/condiciones</li></ul><p><strong>Preguntas de repaso semanal:</strong></p><ul><li>¿Completé mis sesiones planificadas?</li><li>¿Qué puntuaciones obtuve?</li><li>¿Qué te hizo sentir bien? ¿Qué te resultó difícil?</li><li>¿Alguna experiencia de flujo?</li><li>¿Qué debo ajustar?</li></ul><h3 id="fase-7-mantente-motivado" tabindex="-1">Fase 7: Mantente motivado <a class="header-anchor" href="#fase-7-mantente-motivado" aria-label="Permalink to &quot;Fase 7: Mantente motivado&quot;">​</a></h3><p>La motivación fluctúa. Crea sistemas para mantenerla:</p><p><strong>Motivación interna:</strong></p><ul><li>Conéctate con tu “por qué”</li><li>Celebra los pequeños triunfos</li><li>Observe la mejora con el tiempo</li><li>Encuentra alegría en el proceso</li></ul><p><strong>Soporte externo:</strong></p><ul><li>Compañeros de entrenamiento (incluso ocasionalmente)</li><li>Compartir objetivos con alguien</li><li>Únase a comunidades en línea</li><li>Rachas de seguimiento y consistencia</li></ul><p><strong>Cuando la motivación baja:</strong></p><ul><li>Haz una sesión mínima (algo es mejor que nada)</li><li>Cambia tu entorno</li><li>Revisa tu progreso</li><li>Recuerde los éxitos pasados</li><li>Tome un descanso planificado si es necesario</li></ul><h3 id="fase-8-revision-y-adaptacion" tabindex="-1">Fase 8: Revisión y adaptación <a class="header-anchor" href="#fase-8-revision-y-adaptacion" aria-label="Permalink to &quot;Fase 8: Revisión y adaptación&quot;">​</a></h3><p>Su plan debe evolucionar:</p><p><strong>Semanal:</strong> Revisión rápida, ajustes menores <strong>Mensualmente:</strong> Evaluar el progreso hacia los objetivos mensuales, ajustar el enfoque <strong>Trimestral:</strong> Revisión importante, establecer objetivos para el próximo trimestre <strong>Anualmente:</strong> Evaluación completa, nuevo plan anual</p><p><strong>Preguntas para repasar:</strong></p><ul><li>¿Estoy progresando hacia mis objetivos?</li><li>¿Es efectivo mi entrenamiento?</li><li>¿Necesito ejercicios diferentes?</li><li>¿Son mis objetivos aún relevantes?</li><li>¿Qué he aprendido?</li></ul><h2 id="ejemplo-de-plan-de-8-semanas" tabindex="-1">Ejemplo de plan de 8 semanas <a class="header-anchor" href="#ejemplo-de-plan-de-8-semanas" aria-label="Permalink to &quot;Ejemplo de plan de 8 semanas&quot;">​</a></h2><p><strong>Objetivo:</strong> Mejorar la precisión de tiro en un 15%</p><table tabindex="0"><thead><tr><th>Semana</th><th>Enfocar</th><th>Sesiones clave</th></tr></thead><tbody><tr><td>1</td><td>Base</td><td>Prueba de nivel actual, análisis de vídeo</td></tr><tr><td>2</td><td>Técnica</td><td>Identificar y trabajar en los problemas clave</td></tr><tr><td>3</td><td>Repetición</td><td>Práctica de tiro de alto volumen</td></tr><tr><td>4</td><td>Prueba</td><td>Evaluación intermedia, ajuste</td></tr><tr><td>5</td><td>Variación</td><td>Diferentes distancias y ángulos</td></tr><tr><td>6</td><td>Presión</td><td>Añadir consecuencias a los simulacros</td></tr><tr><td>7</td><td>Integración</td><td>Escenarios tipo juego</td></tr><tr><td>8</td><td>Prueba final</td><td>Medir la mejora</td></tr></tbody></table><h2 id="conclusion-clave" tabindex="-1">Conclusión clave <a class="header-anchor" href="#conclusion-clave" aria-label="Permalink to &quot;Conclusión clave&quot;">​</a></h2><blockquote><p>Planifica tu trabajo y luego trabaja según tu plan. Pero prepárate para adaptarte.</p></blockquote><p>El mejor plan es el que realmente seguirás. Empieza con algo sencillo, sé constante y ajústalo a medida que aprendes.</p>',31)),s(g)])}]]);export{u as __pageData,p as default};
